static void InitScene(PlayState* play, s32 spawn) {
    play->curSpawn          = spawn;
    play->linkActorEntry    = nullptr;
    play->unk_11DFC         = nullptr;
    play->setupEntranceList = nullptr;
    play->setupExitList     = nullptr;
    play->cUpElfMsgs        = nullptr;
    play->setupPathList     = nullptr;
    play->numSetupActors    = 0;

    Object_InitBank(play, &play->objectCtx);
    LightContext_Init(play, &play->lightCtx);
    TransitionActor_InitContext(&play->state, &play->transiActorCtx);
    func_80096FD4(play, &play->roomCtx.curRoom);
    YREG(15) = 0;
    gSaveContext.worldMapArea = 0;

    BgCheck_Allocate(&play->colCtx, play, &world_fires_234_scene_collisionHeader);

    play->numRooms = 1;
    play->roomList = sWorldFires234RoomList;

    play->setupEntranceList = sWorldFires234Entrances;
    play->linkActorEntry    = &sWorldFires234PlayerSpawn;
    play->linkAgeOnLoad     = gSaveContext.linkAge;

    s16 linkObjectId = gLinkObjectIds[gSaveContext.linkAge];
    ActorDB_Retrieve(play->linkActorEntry->id)->objectId = linkObjectId;
    Object_Spawn(&play->objectCtx, linkObjectId);

    play->objectCtx.subKeepIndex = Object_Spawn(&play->objectCtx, OBJECT_GAMEPLAY_FIELD_KEEP);

    play->skyboxId = SKYBOX_NORMAL_SKY;
    // What SCENE_CMD_SKYBOX_SETTINGS and SCENE_CMD_SKYBOX_DISABLES set in a normal scene: a clear
    // sky, outdoors, sky and sun drawn. PlayState is re-allocated for each scene without being
    // cleared, so skipping them left the previous scene's values in place - Hyrule Field's storm,
    // Link's house's indoor lighting (sturdy-bassoon#122).
    play->envCtx.unk_17 = play->envCtx.unk_18 = 0;
    play->envCtx.indoors         = 0;
    play->envCtx.skyboxDisabled  = 0;
    play->envCtx.sunMoonDisabled = 0;
    play->sequenceCtx.seqId            = NA_BGM_KAKARIKO_KID;
    // NATURE_ID_NONE, never 0xFF: that is NATURE_ID_DISABLED, a save-context value past the end of
    // the ambience table, which z_kankyo.c played at dusk and crashed the audio thread (sturdy-bassoon#156).
    play->sequenceCtx.natureAmbienceId = NATURE_ID_NONE;

    // Normal scenes get this from SCENE_CMD_SOUND_SETTINGS, which resets the audio heap/SFX
    // banks. Our hand-rolled init bypasses the scene command list entirely, so without this call
    // player SFX (footsteps, jump, roll, etc.) and all other one-shot sound effects are silently
    // dropped later in the audio pipeline (BGM is unaffected - it doesn't go through this reset).
    Audio_QueueSeqCmd(0xF0000000);

    play->envCtx.numLightSettings  = 4;
    play->envCtx.lightSettingsList = sWorldFires234LightSettings;
    WorldFog_SetScene(sWorldFires234WorldFog, ARRAY_COUNT(sWorldFires234WorldFog));
    WorldFog_SetBoundary(sWorldFires234FogBoundary, 2, 0, 4800);
    // The horizon haze band (sturdy-bassoon#168): opaque up to this many degrees above the horizon, then fading
    // out over the next, under world-unit fog.
    WorldFog_SetHaze(2.0f, 2.0f);

    Play_InitEnvironment(play, play->skyboxId);
    GameInteractor_ExecuteAfterSceneCommands(play->sceneNum);
}

// The archive prop lists this room draws (sturdy-bassoon#171): plain archive paths, resolved at
// load and baked. Always emitted, so a map's first prop needs no build - only its archive.
static const char* const sWorldFires234PropLists[] = { "objects/rs_props/world_fires_234_50_51/props", "objects/rs_props/world_fires_234_50_50/props", "objects/rs_props/world_fires_234_51_50/props" };

extern "C" void CustomWorldFires234Scene_InitRoom(PlayState* play, RoomContext* roomCtx) {
    roomCtx->curRoom.echo       = 0;
    roomCtx->curRoom.meshHeader = (MeshHeader*)&world_fires_234_room_0_shapeHeader;

    // Normal scenes get these from SCENE_CMD_ROOM_BEHAVIOR; this hand-rolled init bypasses the
    // scene command list, and nothing on the load path clears them - func_80096FD4 resets only
    // num/segment. Without them the room inherits the previous scene's values: a stale
    // ROOM_BEHAVIOR_TYPE1_2 caps R_RUN_SPEED_LIMIT to 5.0 (the short ledge hop instead of the
    // run-off leap) and disables backflip/sidehop/roll. See issue #39.
    roomCtx->curRoom.behaviorType1 = ROOM_BEHAVIOR_TYPE1_0;
    roomCtx->curRoom.behaviorType2 = ROOM_BEHAVIOR_TYPE2_0;
    roomCtx->curRoom.lensMode      = LENS_MODE_HIDE_ACTORS;

    // 10 entries; play->numSetupActors is an s16 (sturdy-bassoon#45), so this is
    // the authored count and not a truncation of it.
    play->numSetupActors = 10;
    play->setupActorList = sWorldFires234Actors;

    ArchiveProps_DeclareRoom(play, roomCtx, sWorldFires234PropLists, ARRAY_COUNT(sWorldFires234PropLists));

    Player_SetBootData(play, GET_PLAYER(play));
    Actor_SpawnTransitionActors(play, &play->actorCtx);
    GameInteractor_ExecuteAfterSceneCommands(play->sceneNum);
}

extern "C" int CustomWorldFires234Scene_TrySpawn(PlayState* play, s32 sceneId, s32 spawn) {
    if (sceneId != SCENE_WORLD_FIRES_234) {
        return 0;
    }

    SceneTableEntry* scene = &gSceneTable[sceneId];
    scene->unk_13      = 0;
    play->loadedScene  = scene;
    play->sceneNum     = sceneId;
    play->sceneConfig  = scene->config;
    play->sceneSegment = nullptr;

    InitScene(play, spawn);
    func_80096FE8(play, &play->roomCtx);
    GameInteractor_ExecuteOnSceneInit(play->sceneNum);

    SPDLOG_INFO("CustomWorldFires234Scene: spawned scene {} spawn {}", sceneId, spawn);
    return 1;
}
